/* Notera prototype — vanilla JS, local-first. */
(() => {
  'use strict';
  const DB_NAME='notera-local-v1', DB_VERSION=1, STORE='records';
  const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
  const main=$('#main'), overlayRoot=$('#overlayRoot'), toastRoot=$('#toastRoot');
  const svg={back:'<svg viewBox="0 0 24 24"><path d="m15 18-6-6 6-6"/></svg>',book:'<svg viewBox="0 0 24 24"><path d="M4 4.5h5.5A2.5 2.5 0 0 1 12 7v13a2.5 2.5 0 0 0-2.5-2.5H4zM20 4.5h-5.5A2.5 2.5 0 0 0 12 7v13a2.5 2.5 0 0 1 2.5-2.5H20z"/></svg>',file:'<svg viewBox="0 0 24 24"><path d="M6 3h8l4 4v14H6zM14 3v5h4M9 13h6M9 16h6"/></svg>',dots:'<svg viewBox="0 0 24 24"><circle cx="5" cy="12" r="1.3"/><circle cx="12" cy="12" r="1.3"/><circle cx="19" cy="12" r="1.3"/></svg>',search:'<svg viewBox="0 0 24 24"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/></svg>',bookmark:'<svg viewBox="0 0 24 24"><path d="M6 4.5A1.5 1.5 0 0 1 7.5 3h9A1.5 1.5 0 0 1 18 4.5V21l-6-4-6 4z"/></svg>',edit:'<svg viewBox="0 0 24 24"><path d="m4 16.5-.8 4.3 4.3-.8L19.8 7.7a2.5 2.5 0 0 0-3.5-3.5zM14.8 5.7l3.5 3.5"/></svg>',plus:'<svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>',folder:'<svg viewBox="0 0 24 24"><path d="M3 6.5A1.5 1.5 0 0 1 4.5 5H10l2 2h7.5A1.5 1.5 0 0 1 21 8.5v9a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 17.5z"/></svg>',arrow:'<svg viewBox="0 0 24 24"><path d="M7 17 17 7M8.5 7H17v8.5"/></svg>'};
  const STATUSES=['Notes Pending','Notes Completed','Learning & Revision','Exam Ready'];
  const state={tab:'home',screen:'home',subjectId:null,chapterId:null,noteId:null,editor:false,dirty:false,saveTimer:null,editorSnapshot:'',editorBaseline:'',currentSearch:'',returnScreen:'home',lastSearchFocus:false};
  let db;
  function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('IndexedDB is unavailable in this browser.'));return}const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE,{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('Could not open local storage.'))})}
  function idbGetAll(){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readonly'),r=tx.objectStore(STORE).getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)})}
  function idbPut(record){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(record);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||new Error('Local save failed.'));tx.onabort=()=>reject(tx.error||new Error('Local save was interrupted.'))})}
  function idbDelete(key){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
  function idbClear(){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
  const key=(type,id='main')=>`${type}:${id}`; let records=new Map();
  const all=(type)=>[...records.values()].filter(x=>x.type===type);
  const get=(type,id)=>records.get(key(type,id));
  async function save(type,id,data){const r={key:key(type,id),type,id,...data,updatedAt:Date.now()};await idbPut(r);records.set(r.key,r);return r}
  async function remove(type,id){await idbDelete(key(type,id));records.delete(key(type,id))}
  const uid=()=>`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,9)}`;
  const settings=()=>get('settings','main')||{displayName:'Ajaz',theme:'light',recentSearches:[],lastOpenedNote:null};
  const subject=id=>get('subject',id), chapter=id=>get('chapter',id), note=id=>get('note',id);
  const chaptersFor=sid=>all('chapter').filter(c=>c.subjectId===sid), notesFor=cid=>all('note').filter(n=>n.chapterId===cid);
  const subjectForChapter=c=>subject(c?.subjectId), chapterForNote=n=>chapter(n?.chapterId);
  function safeText(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function percent(n,d){return d?Math.round(n/d*100):0}
  function escAttr(s=''){return safeText(s).replace(/`/g,'&#96;')}
  function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;toastRoot.append(el);setTimeout(()=>el.remove(),2800)}
  /* Flat empty state: plain text on the page background, no card. */
  function empty(title,desc,button,label='Create your first item'){return `<div class="empty"><h3>${title}</h3><p>${desc}</p>${button?`<button class="link-btn" data-action="${button}">${svg.plus}${label}</button>`:''}</div>`}
  /* ---- progress rules ---- */
  const WEIGHTS=[0,33,67,100]; // Notes Pending, Notes Completed, Learning & Revision, Exam Ready
  const contribution=c=>{const i=STATUSES.indexOf(c&&c.status);return i<0?0:WEIGHTS[i]};
  // points = sum of per-item values (0-100). Rounded, but 100 only when everything is full and never 0 when something counts.
  function pctOf(points,count){if(!count)return 0;let r=Math.round(points/count);if(r>=100&&points<count*100)r=99;if(r<1&&points>0)r=1;return Math.min(100,Math.max(0,r))}
  const progressOf=list=>pctOf(list.reduce((n,c)=>n+contribution(c),0),list.length);
  const exactCount=(list,status)=>list.filter(c=>c.status===status).length;
  const exactPct=(list,status)=>pctOf(exactCount(list,status)*100,list.length);
  /* ---- names, duplicates, serials ---- */
  const norm=s=>String(s||'').trim().replace(/\s+/g,' ').toLowerCase();
  const dupSubject=(name,exceptId)=>all('subject').some(s=>s.id!==exceptId&&norm(s.name)===norm(name));
  const dupChapter=(sid,name,exceptId)=>chaptersFor(sid).some(c=>c.id!==exceptId&&norm(c.name)===norm(name));
  const dupNote=(cid,title,exceptId)=>notesFor(cid).some(n=>n.id!==exceptId&&norm(n.title)===norm(title));
  const bySerial=(a,b)=>(Number.isInteger(a.serial)?a.serial:1e9)-(Number.isInteger(b.serial)?b.serial:1e9)||String(a.name).localeCompare(String(b.name));
  const nextSerial=sid=>Math.max(0,...chaptersFor(sid).map(c=>Number.isInteger(c.serial)?c.serial:0))+1;
  const serialTaken=(sid,n,exceptId)=>chaptersFor(sid).some(c=>c.id!==exceptId&&c.serial===n);
  function serialField(sid,val,id='chapterSerial',err='serialError'){return `<div class="field"><label for="${id}">Chapter number</label><input id="${id}" type="number" inputmode="numeric" min="1" max="9999" step="1" value="${val??nextSerial(sid)}"><div class="field-error" id="${err}"></div></div>`}
  function readSerial(inputSel,errSel){const el=$(inputSel),err=$(errSel),v=(el?.value||'').trim();const bad=m=>{if(err)err.textContent=m;el?.focus();return null};if(!v)return bad('Enter a chapter number, such as 1, 2 or 3.');if(!/^\d+$/.test(v)||+v<1||+v>9999)return bad('Use a whole number from 1 to 9999.');if(err)err.textContent='';return +v}
  /* ---- subject identity: stored accent + icon derived from the name ---- */
  const ACCENTS=8;
  function pickAccent(excludeId){const used=new Array(ACCENTS).fill(0);all('subject').forEach(s=>{if(s.id!==excludeId&&Number.isInteger(s.accent))used[s.accent%ACCENTS]++});return used.indexOf(Math.min(...used))}
  const ICONS={flask:'<svg viewBox="0 0 24 24"><path d="M9 3h6M10 3v6l-5.2 9.2A1.8 1.8 0 0 0 6.4 21h11.2a1.8 1.8 0 0 0 1.6-2.8L14 9V3M7.5 15h9"/></svg>',math:'<svg viewBox="0 0 24 24"><path d="M6 3h12a1 1 0 0 1 1 1v16a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1zM8 7h8M8 12h.01M12 12h.01M16 12h.01M8 16h.01M12 16h.01M16 16h.01"/></svg>',code:'<svg viewBox="0 0 24 24"><path d="m8 8-4 4 4 4M16 8l4 4-4 4M13.5 5.5l-3 13"/></svg>',globe:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c2.8 3 2.8 15 0 18M12 3c-2.8 3-2.8 15 0 18"/></svg>',history:'<svg viewBox="0 0 24 24"><path d="M3 9.5 12 4l9 5.5M5 10v8M9.7 10v8M14.3 10v8M19 10v8M3 20.5h18"/></svg>',language:svg.edit,book:svg.book};
  const ICON_RULES=[['flask',/scien|chem|bio|physic|botan|zoolog|medic|anatom|\blab/i],['math',/math|algebra|geometr|calcul|statist|arithm|trigon|account/i],['code',/comput|program|coding|\bcode\b|software|\bit\b|informat|\bcs\b|\bdata/i],['globe',/geograph|earth|environment|\bgeo|\bsocial/i],['history',/histor|civic|politic|polity|econom|\blaw|govern|commerce|business/i],['language',/engl|hindi|urdu|language|literat|grammar|writing|essay|poetry|sanskrit|french|german|spanish|arabic/i]];
  function subjectIcon(name){const r=ICON_RULES.find(([,re])=>re.test(name||''));return ICONS[r?r[0]:'book']}
  /* ---- one-time, backward-compatible migration: accent for subjects, serial for chapters ---- */
  async function migrate(){
    const subs=all('subject').sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0);
    for(const s of subs){if(!Number.isInteger(s.accent))await save('subject',s.id,{...s,accent:pickAccent(s.id)})}
    for(const s of subs){const cs=chaptersFor(s.id),missing=cs.filter(c=>!Number.isInteger(c.serial));if(!missing.length)continue;let next=Math.max(0,...cs.filter(c=>Number.isInteger(c.serial)).map(c=>c.serial));missing.sort((a,b)=>String(a.name).localeCompare(String(b.name)));for(const c of missing)await save('chapter',c.id,{...c,serial:++next})}
  }
  function head(title,sub='',back='library',actions=''){return `<div class="page-head"><button class="back-btn" data-action="back" data-back="${back}" aria-label="Go back">${svg.back}</button><div class="page-head-copy"><h1>${safeText(title)}</h1>${sub?`<p>${safeText(sub)}</p>`:''}</div>${actions}</div>`}
  function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening'}
  function subjectCard(s){const p=progressOf(chaptersFor(s.id)),a=(Number.isInteger(s.accent)?s.accent:0)%ACCENTS;return `<button class="subject-card acc-${a}" data-action="open-subject" data-id="${s.id}"><span class="subject-symbol">${subjectIcon(s.name)}</span><span class="sc-name">${safeText(s.name)}</span><span class="sc-pct">${p}%</span><span class="bar" role="progressbar" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100" aria-label="${escAttr(s.name)} progress"><i data-w="${p}"></i></span></button>`}
  function home(){const ss=all('subject').sort((a,b)=>a.name.localeCompare(b.name)),cs=all('chapter'),total=cs.length;
    const overall=progressOf(cs),notesDone=exactPct(cs,STATUSES[1]),learning=exactPct(cs,STATUSES[2]),nDone=exactCount(cs,STATUSES[1]),nLearn=exactCount(cs,STATUSES[2]);
    const count=n=>total?`${n} of ${total} ${total===1?'chapter':'chapters'}`:'';
    return `<section class="hero"><div class="eyebrow">Your personal study space</div><h1>${greeting()}, ${safeText(settings().displayName||'there')}</h1></section>
    <section class="sheet"><i class="grabber"></i><div class="sheet-head"><h2>Syllabus progress</h2></div><p class="sheet-sub">${total?`${total} ${total===1?'chapter':'chapters'} tracked`:'Add chapters to start tracking your progress'}</p><div class="rings">${ringHTML('r-notes','Notes completed',notesDone,count(nDone))}${ringHTML('r-overall','Overall progress',overall,total?'across all subjects':'')}${ringHTML('r-learn','Learning & revision',learning,count(nLearn))}</div>
    <div class="sheet-label"><span>Your subjects</span><button class="add-btn" data-action="create-subject" aria-label="Create subject">${svg.plus}</button></div>${ss.length?`<div class="subject-grid">${ss.map(subjectCard).join('')}</div>`:empty('No subjects yet','Tap + to create your first subject.')}</section>`}
  const RING_C=263.89;
  function ringHTML(kind,label,value,sub){return `<div class="ring-item ${kind}"><div class="ring" role="img" aria-label="${escAttr(label)}: ${value}%"><svg viewBox="0 0 100 100" aria-hidden="true"><circle class="ring-bg" cx="50" cy="50" r="42"/><circle class="ring-arc" cx="50" cy="50" r="42" stroke-dasharray="${RING_C}" stroke-dashoffset="${RING_C}" data-to="${(RING_C*(1-value/100)).toFixed(2)}"/></svg><div class="ring-num">${value}<small>%</small></div></div><div class="ring-label">${label}</div><div class="ring-sub">${sub||'&nbsp;'}</div></div>`}
  function animateProgress(){setTimeout(()=>{$$('.ring-arc',main).forEach(a=>{a.style.strokeDashoffset=a.dataset.to});$$('.bar i',main).forEach(b=>{b.style.width=b.dataset.w+'%'})},30)}
  function library(){const ss=all('subject').sort((a,b)=>a.name.localeCompare(b.name));return `<div class="page-head"><div class="page-head-copy"><h1>Library</h1><p>Subjects, chapters, and notes, all in one place.</p></div><button class="add-btn" data-action="create-subject" aria-label="Create subject">${svg.plus}</button></div>${ss.length?`<div class="subject-grid">${ss.map(subjectCard).join('')}</div>`:empty('Your library is empty','Tap + to create your first subject, then add chapters and notes inside it.')}`}
  function subjectDetail(){const s=subject(state.subjectId);if(!s){state.screen='library';return library()}const cs=chaptersFor(s.id).sort(bySerial),nn=cs.reduce((n,c)=>n+notesFor(c.id).length,0);return `${head(s.name,`${cs.length} ${cs.length===1?'chapter':'chapters'} · ${nn} ${nn===1?'note':'notes'} · ${progressOf(cs)}% progress`,'library',`<button class="row-action" data-action="menu-subject" data-id="${s.id}" aria-label="Subject options">${svg.dots}</button>`)}<section class="section"><div class="section-head"><h2>Chapters</h2><button class="add-btn" data-action="create" data-type="chapter" data-subject="${s.id}" aria-label="Add chapter">${svg.plus}</button></div>${cs.length?`<div class="list">${cs.map(c=>`<div class="list-row clickable" data-action="open-chapter" data-id="${c.id}"><div class="row-icon row-num">${Number.isInteger(c.serial)?c.serial:svg.file}</div><div class="row-main"><h3>${safeText(c.name)}</h3><p>${notesFor(c.id).length} ${notesFor(c.id).length===1?'note':'notes'}</p></div><span class="row-tag tag-s${Math.max(0,STATUSES.indexOf(c.status||STATUSES[0]))}">${safeText(c.status||STATUSES[0])}</span><button class="row-action" data-action="menu-chapter" data-id="${c.id}" aria-label="Chapter options">${svg.dots}</button></div>`).join('')}</div>`:empty('No chapters yet','Tap + to add the first chapter of this subject.')}</section>`}
  function chapterDetail(){const c=chapter(state.chapterId);if(!c){state.screen='library';return library()}const s=subjectForChapter(c),ns=notesFor(c.id).sort((a,b)=>b.updatedAt-a.updatedAt),si=Math.max(0,STATUSES.indexOf(c.status||STATUSES[0]));return `${head(c.name,`${s?.name||'Subject'}${Number.isInteger(c.serial)?` · Chapter ${c.serial}`:''}`,'subject')}<div class="status-row"><label for="chapterStatus">Preparation</label><div class="status-pick tag-s${si}"><i class="status-dot"></i><select class="status-select" id="chapterStatus" aria-label="Chapter preparation status">${STATUSES.map(x=>`<option ${(c.status||STATUSES[0])===x?'selected':''}>${x}</option>`).join('')}</select></div></div><section class="section"><div class="section-head"><h2>Notes</h2><button class="add-btn" data-action="create" data-type="note" data-chapter="${c.id}" aria-label="Create note">${svg.plus}</button></div>${ns.length?`<div class="list">${ns.map(n=>`<div class="list-row clickable" data-action="open-note" data-id="${n.id}"><div class="row-icon">${svg.file}</div><div class="row-main"><h3>${safeText(n.title)}</h3><p>Updated ${new Date(n.updatedAt||Date.now()).toLocaleDateString()}</p></div>${n.bookmarked?`<span class="bm-flag" aria-label="Bookmarked">${svg.bookmark}</span>`:''}<button class="row-action" data-action="menu-note" data-id="${n.id}" aria-label="Note options">${svg.dots}</button></div>`).join('')}</div>`:empty('No notes yet','Tap + to create a note for this chapter.')}</section>`}
  function sanitizeHTML(html){const doc=new DOMParser().parseFromString(`<div>${html||''}</div>`,'text/html'),root=doc.body.firstElementChild;const allowed=new Set(['P','DIV','BR','H1','H2','H3','H4','STRONG','B','EM','I','U','UL','OL','LI','TABLE','THEAD','TBODY','TR','TH','TD','BLOCKQUOTE','MARK','FIGURE','IMG','FIGCAPTION','A','SPAN','HR','SUB','SUP']);const walk=node=>{[...node.childNodes].forEach(child=>{if(child.nodeType===Node.COMMENT_NODE){child.remove();return}if(child.nodeType!==Node.ELEMENT_NODE){if(child.nodeType!==Node.TEXT_NODE)child.remove();return}if(!allowed.has(child.tagName)){const frag=doc.createDocumentFragment();while(child.firstChild)frag.append(child.firstChild);child.replaceWith(frag);return}for(const a of [...child.attributes]){const name=a.name.toLowerCase(),val=a.value;if(child.tagName==='IMG'&&name==='src'){if(!/^data:image\/(png|jpeg|jpg|gif|webp);base64,/i.test(val))child.removeAttribute(a.name);continue}if(child.tagName==='A'&&name==='href'){if(!/^https?:\/\//i.test(val))child.removeAttribute(a.name);continue}if(child.tagName==='SPAN'&&name==='style'){const m=val.match(/background-color:\s*(#[0-9a-f]{3,8}|rgb\([\d ,]+\)|yellow|#fff176)/i);if(m)child.setAttribute('style',`background-color:${m[1]}`);else child.removeAttribute('style');continue}child.removeAttribute(a.name)}if(child.tagName==='IMG'){child.setAttribute('loading','lazy');child.classList.add('note-images')}walk(child)})};walk(root);return root.innerHTML}
  function noteRead(){const n=note(state.noteId);if(!n){state.screen='library';return library()}const c=chapterForNote(n),s=subjectForChapter(c),blank=!/<(img|table|hr)/i.test(n.content||'')&&!(n.content||'').replace(/<[^>]*>|&nbsp;/g,'').trim();return `${head(n.title,`${s?.name||'Subject'} · ${c?.name||'Chapter'}`,state.returnScreen==='search'?'search':state.returnScreen==='bookmarks'?'bookmarks':'chapter',`<div class="head-actions"><button class="row-action bm${n.bookmarked?' on':''}" data-action="toggle-bookmark" data-id="${n.id}" aria-label="${n.bookmarked?'Remove bookmark':'Bookmark note'}" aria-pressed="${n.bookmarked?'true':'false'}">${svg.bookmark}</button><button class="row-action" data-action="menu-note-read" data-id="${n.id}" aria-label="Note options" aria-haspopup="dialog">${svg.dots}</button></div>`)}<article class="note-body"><div class="note-content">${blank?'<p class="muted">This note is empty. Open the ⋯ menu and choose Edit Note to start writing.</p>':sanitizeHTML(n.content)}</div></article>`}
  function bookmarks(){const ns=all('note').filter(n=>n.bookmarked).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));return `<div class="page-head"><div class="page-head-copy"><h1>Bookmarks</h1><p>Your saved notes, always linked to the originals.</p></div></div>${ns.length?`<div class="list">${ns.map(n=>{const c=chapterForNote(n),s=subjectForChapter(c);return `<div class="list-row clickable" data-action="open-note" data-id="${n.id}" data-origin="bookmarks"><div class="row-icon">${svg.bookmark}</div><div class="row-main"><h3>${safeText(n.title)}</h3><p>${safeText(s?.name||'')} · ${safeText(c?.name||'')}</p></div><button class="row-action bm on" data-action="toggle-bookmark" data-id="${n.id}" aria-label="Remove bookmark">${svg.bookmark}</button></div>`}).join('')}</div>`:empty('Nothing saved just yet','Bookmark a note while reading it and it will show up here.')}`}
  function searchScreen(){const q=state.currentSearch.trim();if(!q){const rec=settings().recentSearches||[];return `<div class="page-head"><div class="page-head-copy"><h1>Search</h1><p>Look across subjects, chapters, and note content.</p></div></div><label class="search-box">${svg.search}<input id="searchInput" type="search" placeholder="Search your library…" autocomplete="off" value=""></label><div class="section"><div class="section-head"><h2>Recent searches</h2>${rec.length?'<button class="btn btn-ghost btn-small" data-action="clear-searches">Clear all</button>':''}</div>${rec.length?`<div class="search-recents">${rec.map(x=>`<div class="recent-item"><button data-action="rerun-search" data-query="${escAttr(x)}">${safeText(x)}</button><span class="muted">${svg.arrow}</span></div>`).join('')}</div>`:empty('Search history is empty','Search for a topic, then your recent searches will be kept here.')}</div>`}
    const low=q.toLowerCase(),ss=all('subject').filter(x=>x.name.toLowerCase().includes(low)),cs=all('chapter').filter(x=>x.name.toLowerCase().includes(low)),ns=all('note').filter(x=>x.title.toLowerCase().includes(low)||(x.content||'').replace(/<[^>]*>/g,' ').toLowerCase().includes(low));const count=ss.length+cs.length+ns.length;return `<div class="page-head"><div class="page-head-copy"><h1>Search</h1></div></div><label class="search-box">${svg.search}<input id="searchInput" type="search" placeholder="Search your library…" autocomplete="off" value="${escAttr(q)}"><button class="row-action" data-action="clear-query" aria-label="Clear search">×</button></label>${count?`${ss.length?resultGroup('Subjects',ss.map(s=>`<div class="list-row clickable" data-action="open-subject" data-id="${s.id}"><div class="row-icon">${svg.folder}</div><div class="row-main"><h3>${safeText(s.name)}</h3><p>Subject</p></div><i class="chev"></i></div>`).join('')):''}${cs.length?resultGroup('Chapters',cs.map(c=>`<div class="list-row clickable" data-action="search-open-chapter" data-id="${c.id}"><div class="row-icon">${svg.file}</div><div class="row-main"><h3>${safeText(c.name)}</h3><p>${safeText(subjectForChapter(c)?.name||'')}</p></div><i class="chev"></i></div>`).join('')):''}${ns.length?resultGroup('Notes',ns.map(n=>{const c=chapterForNote(n),s=subjectForChapter(c);return `<div class="list-row clickable" data-action="open-note" data-id="${n.id}" data-origin="search"><div class="row-icon">${svg.file}</div><div class="row-main"><h3>${safeText(n.title)}</h3><p>${safeText(s?.name||'')} · ${safeText(c?.name||'')}</p></div><i class="chev"></i></div>`}).join('')):''}`:empty('No matches found',`No results for “${q.replace(/[<>]/g,'')}”. Try another word or a shorter phrase.`)}`}
  function resultGroup(title,html){return `<section class="result-group"><h2>${title}</h2><div class="list">${html}</div></section>`}
  function settingsScreen(){const s=settings(),theme=s.theme||'light';let usage='';try{usage=`${new Blob([...records.values()].map(x=>JSON.stringify(x))).size.toLocaleString()} bytes of indexed data`}catch{}return `<div class="page-head"><div class="page-head-copy"><h1>Settings</h1><p>A few details to make Notera feel like yours.</p></div></div><section class="settings-group"><h2>Personalisation</h2><div class="list"><div class="setting-row"><div><h3>Display name</h3><p>Used in your Home greeting.</p></div><div class="setting-control"><input id="displayName" type="text" maxlength="40" value="${escAttr(s.displayName||'')}" aria-label="Display name"></div></div><div class="setting-row"><div><h3>Greeting preview</h3><p>Updates with your local time.</p></div><strong style="font-size:12.5px;font-weight:500">${greeting()}</strong></div></div></section><section class="settings-group"><h2>Appearance</h2><div class="list"><div class="setting-row"><div><h3>Theme</h3><p>Choose a comfortable reading mode.</p></div><div class="segmented"><button data-action="theme" data-theme="light" class="${theme==='light'?'selected':''}">Light</button><button data-action="theme" data-theme="dark" class="${theme==='dark'?'selected':''}">Dark</button></div></div></div></section><section class="settings-group"><h2>Storage & data</h2><div class="list"><div class="setting-row"><div><h3>Local storage</h3><p>Saved on this browser · ${usage||'size unavailable'}</p></div><span style="color:var(--green);font-size:12px;font-weight:750">On device</span></div><div class="setting-row"><div><h3>Export backup</h3><p>Download your notes, settings, and history as JSON.</p></div><button class="btn btn-secondary btn-small" data-action="export">Export</button></div><div class="setting-row"><div><h3>Import backup</h3><p>Restore or merge a Notera JSON backup.</p></div><button class="btn btn-secondary btn-small" data-action="import">Import</button></div></div></section><section class="settings-group"><h2>About</h2><div class="list"><div class="setting-row"><div><h3>Notera</h3><p>A calm, local-first space for personal study notes.</p></div><span class="subtle">Prototype 0.1.0</span></div><div class="setting-row"><div><h3>Privacy by design</h3><p>Your content stays in this browser. No account or cloud sync.</p></div></div></div></section><p class="footer-note">Made for thoughtful learning · Notera prototype</p>`}
  function render(){const dark=settings().theme==='dark';document.body.classList.toggle('dark',dark);const tc=document.querySelector('meta[name="theme-color"]');if(tc)tc.content=dark?'#101D24':'#D5E6EC';main.dataset.screen=state.editor?'editor':state.screen;document.body.dataset.screen=main.dataset.screen;document.body.classList.toggle('reading',main.dataset.screen==='note');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));let html='';if(state.editor){renderEditor();return}switch(state.screen){case'home':html=home();break;case'library':html=library();break;case'subject':html=subjectDetail();break;case'chapter':html=chapterDetail();break;case'note':html=noteRead();break;case'search':html=searchScreen();break;case'bookmarks':html=bookmarks();break;case'settings':html=settingsScreen();break;default:state.screen='home';html=home()}main.innerHTML=html;animateProgress()}
  function go(tab){if(state.editor){if(!confirmLeave())return}state.tab=tab;state.screen=tab;state.editor=false;state.noteId=tab==='note'?state.noteId:null;render();main.focus({preventScroll:true});window.scrollTo(0,0)}
  function confirmLeave(){if(state.dirty){const ok=confirm('Your latest edits are still saving. Leave this editor?');if(!ok)return false}return true}
  function showModal(title,sub,body,buttons=''){overlayRoot.innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${escAttr(title)}"><h2>${safeText(title)}</h2><p class="modal-sub">${safeText(sub||'')}</p>${body}<div class="modal-actions">${buttons||'<button class="btn btn-secondary" data-action="close-modal">Cancel</button>'}</div></section></div>`;const first=$('input,select,textarea,button',overlayRoot);if(first)setTimeout(()=>{if(!overlayRoot.contains(document.activeElement))first.focus()},50)}
  function closeModal(){overlayRoot.innerHTML=''}
  function createModal(type='subject',sid=null,cid=null){const options=type==='any'?`<div class="list"><button class="list-row clickable" data-action="create" data-type="subject"><div class="row-icon">${svg.folder}</div><div class="row-main"><h3>Subject</h3><p>Start a new subject collection</p></div><i class="chev"></i></button><button class="list-row clickable" data-action="create" data-type="chapter"><div class="row-icon">${svg.file}</div><div class="row-main"><h3>Chapter</h3><p>Add a chapter to a subject</p></div><i class="chev"></i></button><button class="list-row clickable" data-action="create" data-type="note"><div class="row-icon">${svg.book}</div><div class="row-main"><h3>Note</h3><p>Write a new note in a chapter</p></div><i class="chev"></i></button></div>`:'';if(type==='any'){showModal('Create something','Choose what you want to add.',options);return}const title=type==='subject'?'New subject':type==='chapter'?'New chapter':'New note';let fields='';if(type==='chapter'&&!sid){const ss=all('subject');fields=`<div class="field"><label for="formSubject">Subject</label><select id="formSubject" required>${ss.map(s=>`<option value="${s.id}">${safeText(s.name)}</option>`).join('')}</select>${!ss.length?'<div class="field-error">Create a subject first.</div>':''}</div>`}if(type==='note'&&!cid){const cs=all('chapter');fields=`<div class="field"><label for="formChapter">Chapter</label><select id="formChapter" required>${cs.map(c=>`<option value="${c.id}">${safeText(subjectForChapter(c)?.name||'')} · ${safeText(c.name)}</option>`).join('')}</select>${!cs.length?'<div class="field-error">Create a chapter first.</div>':''}</div>`}fields+=`<div class="field"><label for="itemName">${type==='subject'?'Subject name':type==='chapter'?'Chapter name':'Note title'}</label><input id="itemName" maxlength="120" required placeholder="${type==='subject'?'e.g. Science':type==='chapter'?'e.g. Life Processes':'e.g. Complete Notes'}"><div class="field-error" id="formError"></div></div>${type==='chapter'?serialField(sid||all('subject')[0]?.id):''}`;showModal(title,type==='note'?'Give this note a clear, useful title.':'You can rename this anytime.',fields,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-create" data-type="${type}" data-subject="${sid||''}" data-chapter="${cid||''}">Create</button>`)}
  async function submitCreate(type,sid,cid){const input=$('#itemName'),name=input?.value.trim(),err=$('#formError');const fail=m=>{if(err)err.textContent=m;input?.focus()};if(!name)return fail(`Please enter a ${type==='note'?'title':'name'}.`);
    if(type==='subject'){if(dupSubject(name))return fail('This subject already exists.');const id=uid();await save('subject',id,{name,accent:pickAccent()});state.subjectId=id;state.screen='subject';state.tab='library'}
    else if(type==='chapter'){sid=sid||$('#formSubject')?.value;if(!sid||!subject(sid))return fail('Please create or choose a subject first.');if(dupChapter(sid,name))return fail('This chapter already exists in this subject.');const serial=readSerial('#chapterSerial','#serialError');if(serial==null)return;if(serialTaken(sid,serial)){$('#serialError').textContent=`Chapter ${serial} already exists in this subject. Try ${nextSerial(sid)}.`;$('#chapterSerial').focus();return}const id=uid();await save('chapter',id,{name,subjectId:sid,status:STATUSES[0],serial});state.subjectId=sid;state.chapterId=id;state.screen='chapter';state.tab='library'}
    else{cid=cid||$('#formChapter')?.value;if(!cid||!chapter(cid))return fail('Please create or choose a chapter first.');if(dupNote(cid,name)&&input.dataset.warned!==norm(name)){input.dataset.warned=norm(name);const b=$('[data-action="submit-create"]');if(b)b.textContent='Create anyway';return fail('A note with this title already exists in this chapter. Tap Create anyway to keep both.')}const id=uid();await save('note',id,{title:name,chapterId:cid,content:'<p></p>',bookmarked:false,versions:[]});state.chapterId=cid;state.noteId=id;state.screen='note';state.tab='library';state.returnScreen='chapter'}
    closeModal();render();if(type==='note'){state.editor=true;state.editorSnapshot='';renderEditor()}toast(`${type[0].toUpperCase()+type.slice(1)} created.`)}
  function renameModal(type,id){const item=get(type,id);if(!item)return;showModal(`Rename ${type}`,`Choose a new name for this ${type}.`,`<div class="field"><label for="renameValue">Name</label><input id="renameValue" maxlength="120" value="${escAttr(item.name||item.title||'')}"><div class="field-error" id="renameError"></div></div>${type==='chapter'?serialField(item.subjectId,item.serial,'renameSerial','renameSerialError'):''}`,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-rename" data-type="${type}" data-id="${id}">Save</button>`)}
  async function submitRename(type,id){const inp=$('#renameValue'),err=$('#renameError'),val=inp?.value.trim();const fail=m=>{if(err)err.textContent=m;inp?.focus()};if(!val)return fail('A name is required.');const item=get(type,id);if(!item)return;const patch={};
    if(type==='subject'&&dupSubject(val,id))return fail('This subject already exists.');
    if(type==='chapter'){if(dupChapter(item.subjectId,val,id))return fail('This chapter already exists in this subject.');const serial=readSerial('#renameSerial','#renameSerialError');if(serial==null)return;if(serialTaken(item.subjectId,serial,id)){$('#renameSerialError').textContent=`Chapter ${serial} already exists in this subject.`;$('#renameSerial').focus();return}patch.serial=serial}
    if(type==='note'&&dupNote(item.chapterId,val,id)&&inp.dataset.warned!==norm(val)){inp.dataset.warned=norm(val);const b=$('[data-action="submit-rename"]');if(b)b.textContent='Save anyway';return fail('A note with this title already exists in this chapter. Tap Save anyway to keep both.')}
    const field=type==='note'?'title':'name';await save(type,id,{...item,[field]:val,...patch});closeModal();render();toast('Saved.')}
  function deleteModal(type,id){const item=get(type,id);if(!item)return;const label=item.name||item.title;showModal(`Delete ${type}?`,`“${label}” will be removed from this device. This cannot be undone.`,type==='subject'?'<p class="subtle">Its chapters, notes, bookmarks, and local image content will also be deleted.</p>':type==='chapter'?'<p class="subtle">Its notes and bookmarks will also be deleted.</p>':'<p class="subtle">This note and its local version history will be deleted.</p>',`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-danger" data-action="confirm-delete" data-type="${type}" data-id="${id}">Delete</button>`)}
  async function deleteItem(type,id){if(type==='subject'){for(const c of chaptersFor(id))await deleteItem('chapter',c.id);await remove('subject',id);state.screen='library';state.tab='library'}else if(type==='chapter'){for(const n of notesFor(id))await deleteItem('note',n.id);await remove('chapter',id);state.screen='subject';state.tab='library'}else{await remove('note',id);if(settings().lastOpenedNote===id)await save('settings','main',{...settings(),lastOpenedNote:null});if(state.noteId===id){state.noteId=null;state.editor=false;state.screen='chapter';state.tab='library'}}closeModal();render();toast(`${type[0].toUpperCase()+type.slice(1)} deleted.`)}
  async function openNote(id,origin='chapter'){const n=note(id);if(!n)return toast('This note is no longer available.',true);if(state.editor&&!confirmLeave())return;state.noteId=id;state.returnScreen=origin;state.screen='note';state.tab=origin==='search'?'search':origin==='bookmarks'?'bookmarks':'library';await save('settings','main',{...settings(),lastOpenedNote:id});state.editor=false;render();window.scrollTo(0,0)}
  function renderEditor(){const n=note(state.noteId);if(!n){state.editor=false;render();return}main.dataset.screen='editor';main.innerHTML=`${head('Edit note','Changes save on this device','note',`<button class="btn btn-primary btn-small" data-action="done-edit">Done</button>`)}<div class="field" style="margin:0 0 12px"><label for="editorTitle">Note title</label><input id="editorTitle" value="${escAttr(n.title)}" maxlength="120" class="title-field"></div><div class="editor-wrap"><div class="editor-tools" role="toolbar" aria-label="Text formatting"><button class="tool-btn" data-cmd="formatBlock" data-value="h2" title="Heading">H₂</button><button class="tool-btn" data-cmd="formatBlock" data-value="h3" title="Subheading">H₃</button><button class="tool-btn" data-cmd="bold" title="Bold"><b>B</b></button><button class="tool-btn" data-cmd="italic" title="Italic"><i>I</i></button><button class="tool-btn" data-cmd="underline" title="Underline"><u>U</u></button><button class="tool-btn" data-cmd="insertUnorderedList" title="Bulleted list">• List</button><button class="tool-btn" data-cmd="insertOrderedList" title="Numbered list">1. List</button><button class="tool-btn" data-cmd="highlight" title="Highlight">▰</button><button class="tool-btn" data-cmd="definition" title="Definition callout">Definition</button><button class="tool-btn" data-cmd="important" title="Important point">Important</button><button class="tool-btn" data-cmd="table" title="Insert table">▦ Table</button><button class="tool-btn" data-cmd="image" title="Insert image">▧ Image</button><button class="tool-btn" data-cmd="undo" title="Undo">↶</button><button class="tool-btn" data-cmd="redo" title="Redo">↷</button></div><div id="editorSurface" class="editor-surface" contenteditable="true" role="textbox" aria-multiline="true" data-placeholder="Start writing your notes… Paste from ChatGPT or another app to bring your notes here.">${sanitizeHTML(n.content||'')}</div><div class="editor-bottom"><span class="save-state"><i class="save-dot" id="saveDot"></i><span id="saveText">Saved locally</span></span><button class="btn btn-ghost btn-small" data-action="history" data-id="${n.id}">Version history</button></div></div>`;state.dirty=false;state.editorSnapshot=n.content||'';state.editorBaseline=n.content||'';const surface=$('#editorSurface');surface.addEventListener('input',scheduleAutoSave);surface.addEventListener('paste',handlePaste);$('#editorTitle').addEventListener('input',scheduleAutoSave);}
  function setSaveState(label,kind=''){const t=$('#saveText'),d=$('#saveDot');if(t)t.textContent=label;if(d)d.className='save-dot '+kind}
  function scheduleAutoSave(){state.dirty=true;setSaveState('Saving…','saving');clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>persistEditor(false),450)}
  async function persistEditor(makeVersion=false){if(!state.editor)return;const n=note(state.noteId),surface=$('#editorSurface');if(!n||!surface)return;const title=$('#editorTitle')?.value.trim()||n.title;const content=sanitizeHTML(surface.innerHTML);try{let versions=n.versions||[];if(makeVersion&&state.editorBaseline!==content){versions=[...versions,{content:state.editorBaseline||'',title:n.title,at:Date.now()}].slice(-20)}await save('note',n.id,{...n,title,content,versions});state.dirty=false;state.editorSnapshot=content;if(makeVersion)state.editorBaseline=content;setSaveState('Saved locally');}catch(e){setSaveState('Save failed','failed');toast('Could not save this note locally. Check browser storage space.',true)}}
  async function finishEdit(){clearTimeout(state.saveTimer);await persistEditor(true);state.editor=false;state.screen='note';render()}
  function handlePaste(e){const html=e.clipboardData?.getData('text/html'),text=e.clipboardData?.getData('text/plain');if(html){e.preventDefault();const clean=sanitizeHTML(html);document.execCommand('insertHTML',false,clean)}else if(text){e.preventDefault();const htmlText=safeText(text).split(/\n{2,}/).map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('');document.execCommand('insertHTML',false,htmlText)}scheduleAutoSave()}
  function editorCommand(cmd,value){const ed=$('#editorSurface');if(!ed)return;ed.focus();if(cmd==='highlight'){document.execCommand('insertHTML',false,`<mark>${getSelectedText()||'highlighted text'}</mark>`)}else if(cmd==='definition'||cmd==='important'){const label=cmd==='definition'?'Definition':'Important point';document.execCommand('insertHTML',false,`<blockquote><p><strong>${label}:</strong> </p></blockquote>`)}else if(cmd==='table'){document.execCommand('insertHTML',false,'<table><tbody><tr><th>Heading</th><th>Heading</th></tr><tr><td>Text</td><td>Text</td></tr></tbody></table><p></p>')}else if(cmd==='image'){$('#imagePicker').click();return}else if(cmd==='formatBlock'){document.execCommand('formatBlock',false,value)}else document.execCommand(cmd,false,null);scheduleAutoSave()}
  function getSelectedText(){const s=window.getSelection();return s? s.toString():''}
  async function imageSelected(file){if(!file)return;if(file.size>4*1024*1024){toast('Choose an image under 4 MB for this browser prototype.',true);return}if(!file.type.startsWith('image/')){toast('Please choose an image file.',true);return}try{const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});const ed=$('#editorSurface');if(!ed)return;ed.focus();document.execCommand('insertHTML',false,`<figure><img src="${data}" alt="${escAttr(file.name)}"><figcaption contenteditable="true">Add image caption</figcaption></figure><p></p>`);scheduleAutoSave()}catch{toast('This image could not be read. Please try another file.',true)}}
  function historyModal(id){const n=note(id);if(!n)return;const versions=(n.versions||[]).slice().reverse();const html=versions.length?versions.map((v,i)=>`<div class="history-item"><div class="row-main"><h3>Version ${versions.length-i}</h3><p>${safeText(v.title||n.title)}</p><time>${new Date(v.at).toLocaleString()}</time></div><button class="btn btn-secondary btn-small" data-action="restore-version" data-id="${id}" data-index="${(n.versions||[]).length-1-i}">Restore</button></div>`).join(''):'<div class="empty"><h3>No previous versions</h3><p>Older versions are saved when you finish editing after making changes.</p></div>';showModal('Version history','Restore a previous saved version. Your current version will be preserved.',`<div class="list">${html}</div>`,'<button class="btn btn-secondary" data-action="close-modal">Close</button>')}
  async function restoreVersion(id,index){const n=note(id),v=n?.versions?.[index];if(!n||!v)return;showModal('Restore this version?','The current note will be saved into history before restoring the selected version.',`<p class="subtle">Version from ${new Date(v.at).toLocaleString()} will replace the current content.</p>`,`<button class="btn btn-secondary" data-action="history" data-id="${id}">Cancel</button><button class="btn btn-primary" data-action="confirm-restore" data-id="${id}" data-index="${index}">Restore version</button>`)}
  async function confirmRestore(id,index){const n=note(id),v=n?.versions?.[index];if(!n||!v)return;const versions=[...(n.versions||[]),{content:n.content,title:n.title,at:Date.now()}].slice(-20);await save('note',id,{...n,title:v.title||n.title,content:v.content,versions});closeModal();state.editor=false;state.screen='note';render();toast('Previous version restored.')}
  function exportBackup(){try{const data={format:'notera-backup',version:1,exportedAt:new Date().toISOString(),records:[...records.values()]};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`notera-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Backup exported.')}catch{toast('Export failed. Please try again.',true)}}
  function importBackup(){const body=`<div class="field"><label for="backupFile">Backup JSON file</label><input id="backupFile" type="file" accept=".json,application/json"><div class="field-error" id="importError"></div></div><div class="field"><label for="importMode">Import method</label><select id="importMode"><option value="merge">Merge with existing content (recommended)</option><option value="replace">Replace all current content</option></select></div><p class="subtle">Only Notera JSON backups are accepted. Replacing permanently removes current local content.</p>`;showModal('Import a backup','Choose a backup file and how it should be applied.',body,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="read-import">Continue</button>`)}
  async function readImport(){const file=$('#backupFile')?.files?.[0],err=$('#importError');if(!file){err.textContent='Choose a backup file first.';return}try{if(file.size>15*1024*1024)throw new Error('File is too large (15 MB maximum).');const parsed=JSON.parse(await file.text());if(parsed.format!=='notera-backup'||!Array.isArray(parsed.records))throw new Error('This file is not a valid Notera backup.');const allowed=new Set(['subject','chapter','note','settings']);for(const r of parsed.records){if(!r||!allowed.has(r.type)||typeof r.id!=='string'||typeof r.key!=='string')throw new Error('The backup contains invalid records.');if(r.type==='note'&&typeof r.content!=='string')r.content='';}const mode=$('#importMode').value;showModal(mode==='replace'?'Replace current data?':'Merge this backup?',mode==='replace'?'All existing local content will be replaced with the backup.':'Items with matching IDs will be updated; other existing items stay.',`<p class="subtle">${parsed.records.length} records found in this backup.</p>`,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-import" data-mode="${mode}" data-records="${encodeURIComponent(JSON.stringify(parsed.records))}">${mode==='replace'?'Replace data':'Merge data'}</button>`)}catch(e){if(err)err.textContent=e.message||'Could not read this file.'}}
  async function confirmImport(mode,serialized){try{const incoming=JSON.parse(decodeURIComponent(serialized));if(mode==='replace'){await idbClear();records.clear()}for(const r of incoming){const copy={...r};if(copy.type==='note')copy.content=sanitizeHTML(copy.content||'');await idbPut(copy);records.set(copy.key,copy)}for(const n of all('note'))if(!chapter(n.chapterId))await remove('note',n.id);for(const c of all('chapter'))if(!subject(c.subjectId))await remove('chapter',c.id);await migrate();closeModal();state.editor=false;state.screen='home';state.tab='home';render();toast('Backup imported successfully.')}catch{toast('Import failed. Existing data has been kept where possible.',true)}}
  async function clearSearches(){await save('settings','main',{...settings(),recentSearches:[]});render()}
  async function recordSearch(q){if(!q.trim())return;const s=settings(),arr=[q.trim(),...(s.recentSearches||[]).filter(x=>x.toLowerCase()!==q.trim().toLowerCase())].slice(0,8);await save('settings','main',{...s,recentSearches:arr})}
  function menuFor(type,id){const item=get(type,id);if(!item)return;showModal(`${item.name||item.title}`,'Choose an action.',`<div class="list"><button class="list-row clickable" data-action="rename" data-type="${type}" data-id="${id}"><div class="row-icon">${svg.edit}</div><div class="row-main"><h3>Rename</h3></div></button><button class="list-row clickable" data-action="delete" data-type="${type}" data-id="${id}"><div class="row-icon" style="color:var(--danger)">×</div><div class="row-main"><h3>Delete</h3></div></button></div>`,'<button class="btn btn-secondary" data-action="close-modal">Close</button>')}
  function noteMenu(id){const n=note(id);if(!n)return;showModal(n.title,'Choose an action.',`<div class="list"><button class="list-row clickable" data-action="edit-note" data-id="${id}"><div class="row-icon">${svg.edit}</div><div class="row-main"><h3>Edit Note</h3></div></button><button class="list-row clickable" data-action="history" data-id="${id}"><div class="row-icon">${svg.file}</div><div class="row-main"><h3>View History</h3></div></button></div>`,'<button class="btn btn-secondary" data-action="close-modal">Close</button>')}
  async function handleAction(el){const a=el.dataset.action,id=el.dataset.id,type=el.dataset.type;switch(a){case'create':createModal(el.dataset.type||'any',el.dataset.subject||state.subjectId,el.dataset.chapter||state.chapterId);break;case'create-subject':createModal('subject');break;case'create-chapter':createModal('chapter',state.subjectId);break;case'create-note':createModal('note',null,state.chapterId);break;case'submit-create':await submitCreate(type,el.dataset.subject,el.dataset.chapter);break;case'open-subject':state.subjectId=id;state.screen='subject';state.tab='library';render();break;case'open-chapter':state.chapterId=id;state.screen='chapter';state.tab='library';render();break;case'search-open-chapter':{const c=chapter(id);state.subjectId=c?.subjectId;state.chapterId=id;state.screen='chapter';state.tab='library';render();break}case'open-note':await openNote(id,el.dataset.origin||'chapter');break;case'edit-note':closeModal();state.editor=true;state.screen='note';renderEditor();window.scrollTo(0,0);break;case'done-edit':await finishEdit();break;case'toggle-bookmark':{const n=note(id);if(n){await save('note',id,{...n,bookmarked:!n.bookmarked});render();toast(n.bookmarked?'Bookmark removed.':'Note bookmarked.')}break}case'rename':closeModal();renameModal(type,id);break;case'submit-rename':await submitRename(type,id);break;case'delete':closeModal();deleteModal(type,id);break;case'confirm-delete':await deleteItem(type,id);break;case'menu-subject':menuFor('subject',id);break;case'menu-chapter':menuFor('chapter',id);break;case'menu-note':menuFor('note',id);break;case'menu-note-read':noteMenu(id);break;case'back':if(state.editor){await finishEdit();return}if(el.dataset.back==='subject'){state.screen='subject'}else if(el.dataset.back==='chapter'){state.screen='chapter'}else{state.screen=el.dataset.back||'library';state.tab=state.screen==='subject'||state.screen==='chapter'||state.screen==='note'?'library':state.screen}render();break;case'close-modal':closeModal();break;case'theme':await save('settings','main',{...settings(),theme:el.dataset.theme});render();toast(`${el.dataset.theme==='dark'?'Dark':'Light'} mode enabled.`);break;case'export':exportBackup();break;case'import':importBackup();break;case'read-import':await readImport();break;case'confirm-import':await confirmImport(el.dataset.mode,el.dataset.records);break;case'history':historyModal(id);break;case'restore-version':restoreVersion(id,Number(el.dataset.index));break;case'confirm-restore':await confirmRestore(id,Number(el.dataset.index));break;case'clear-searches':await clearSearches();break;case'rerun-search':state.currentSearch=el.dataset.query;await recordSearch(state.currentSearch);render();$('#searchInput')?.focus();break;case'clear-query':state.currentSearch='';render();$('#searchInput')?.focus();break;case'backdrop':if(el===event.target)closeModal();break;}}
  let busy=false;document.addEventListener('click',async e=>{const nav=e.target.closest('[data-tab]');if(nav){go(nav.dataset.tab);return}const act=e.target.closest('[data-action]');if(act){if(act.dataset.action==='backdrop'&&e.target!==act)return;if(busy)return;busy=true;try{await handleAction(act)}catch(err){console.error(err);toast('That action could not be completed. Please try again.',true)}finally{busy=false}return}const tool=e.target.closest('[data-cmd]');if(tool){editorCommand(tool.dataset.cmd,tool.dataset.value);return}});
  document.addEventListener('change',async e=>{if(e.target.id==='chapterStatus'){const c=chapter(state.chapterId);if(c){await save('chapter',c.id,{...c,status:e.target.value});render();toast('Chapter status updated.')}}if(e.target.id==='imagePicker'){await imageSelected(e.target.files?.[0]);e.target.value=''}});
  document.addEventListener('input',e=>{if(e.target.id==='itemName'||e.target.id==='renameValue'){delete e.target.dataset.warned;const er=$('#formError')||$('#renameError');if(er)er.textContent='';const b=$('[data-action="submit-create"]')||$('[data-action="submit-rename"]');if(b&&/anyway/.test(b.textContent))b.textContent=b.dataset.action==='submit-create'?'Create':'Save'}if(e.target.id==='searchInput'){state.currentSearch=e.target.value;const pos=e.target.selectionStart;render();const input=$('#searchInput');if(input){input.focus();input.setSelectionRange(pos,pos)}}if(e.target.id==='displayName'){clearTimeout(e.target._timer);const val=e.target.value;const input=e.target;input._timer=setTimeout(async()=>{await save('settings','main',{...settings(),displayName:val.trim()||'there'});const focused=document.activeElement===input;const pos=input.selectionStart;render();const next=$('#displayName');if(focused&&next){next.focus();next.setSelectionRange(pos,pos)}},350)}});
  document.addEventListener('change',async e=>{if(e.target.id==='searchInput'){const q=e.target.value.trim();await recordSearch(q)}});
  document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing&&e.target.matches?.('.modal input:not([type=file])')){e.preventDefault();$('.modal-actions .btn-primary',overlayRoot)?.click();return}if(e.key==='Escape'&&overlayRoot.innerHTML)closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&state.editor){e.preventDefault();persistEditor(true)}});
  window.addEventListener('beforeunload',e=>{if(state.editor&&state.dirty){e.preventDefault();e.returnValue=''}});
  async function init(){try{db=await openDB();const rows=await idbGetAll();records=new Map(rows.map(r=>[r.key,r]));if(!get('settings','main'))await save('settings','main',{displayName:'Ajaz',theme:'light',recentSearches:[],lastOpenedNote:null});try{await migrate()}catch(e){console.error('migration skipped',e)}render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){main.innerHTML=`<div class="empty"><div class="empty-symbol">!</div><h3>Local storage unavailable</h3><p>Notera needs browser storage to save your notes. Try opening it in a modern browser or enable site storage, then reload.</p><button class="btn btn-primary" onclick="location.reload()">Try again</button></div>`;console.error(e)}}
  init();
})();
